#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/heavisidef.h"

/**
* Evaluates the Heavisidef function.
*
* @param x 				input value
* @param continuity 	continuity option
* @return				function value
*
* @example
* float v = stdlib_base_heavisidef( 3.14, 0 );
* // returns 1.0
*
* @example
* float v = stdlib_base_heavisidef( -3.14, 1 );
* // returns 0.0
*
* @example
* float v = stdlib_base_heavisidef( 0.0, -1 );
* // returns NaN
*
* @example
* float v = stdlib_base_heavisidef( 0.0, 2 );
* // returns 0.5
*
* @example
* float v = stdlib_base_heavisidef( 0.0, 0 );
* // returns 0.0
*
* @example
* float v = stdlib_base_heavisidef( 0.0, 1 );
* // returns 1.0
*
* @example
* float v = stdlib_base_heavisidef( NaN, 0 );
* // returns NaN
*/
float stdlib_base_heavisidef( const float x, int continuity ) {
	if ( stdlib_base_is_nanf( x )) {
		return 0.0f/0.0f;
	}
	if ( x > 0.0 ) {
		return 1.0f;
	}
	if ( x == 0.0 ) {
		if ( continuity == 0 ) {
			return 0.0f;
		}else if ( continuity == 1 ) {
			return 1.0f;
		}else if ( continuity == 2 ) {
			return 0.5f;
		}
		// Default behaviour is discontinuity
		return 0.0f/0.0f;
	}
	return 0.0f;
}
